INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65769984', 65769984, 'analyze_legacy', 'Kab. Tuban', 'kabkota', 'PUSKESMAS MONTONG', 'Pengadaan Pemeliharaan Alat Kesehatan Puskesmas Montong', 'Jasa Lainnya', 'Pengadaan Langsung', 'Jawa Timur, Tuban (Kab.)', 8500000, 'January 2026', 'BLUD', 1, 1, '1 paket', 'Pengadaan Pemeliharaan Alat Kesehatan', 'Pemeliharaan Alat Hematology Analyzer, dan Alat Kesehatan lainnya', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 524226);
INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62102363', 62102363, 'analyze_legacy', 'Kementerian Imigrasi dan Pemasyarakatan', 'central', 'DIREKTORAT JENDERAL IMIGRASI', 'Pemeliharaan Switch 24 Port Kegiatan Pemeliharaan Perangkat Keras pada Direktorat Jenderal Imigrasi Tahun Anggaran 2026', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Selatan (Kota)', 4500000000, 'January 2026', 'APBN - PNBP (D)', 1, 1, '1.0 Thn', 'Melakukan pemeliharaan rutin dan insidental terhadap perangkat Switch 24 Port untuk menjamin stabilitas konektivitas dan keamanan jaringan. Lingkup pekerjaan mencakup pemeriksaan fisik (kebersihan/suhu), validasi koneksi dan konfigurasi (VLAN/Trunk), pemantauan kinerja (traffic monitoring), tindakan preventif (reboot/update firmware), penanganan gangguan (troubleshooting), serta penggantian komponen pendukung (kabel/SFP) jika diperlukan.', '1. Pemeriksaan Fisik: Pengecekan mounting rak, kondisi port/kabel, fungsi LED, serta pembersihan debu pada ventilasi untuk mencegah overheat. 2. Koneksi & Konfigurasi: Validasi koneksi aktif (ping tool), penandaan port tidak terpakai, pengecekan VLAN/Trunk, Port Security, update firmware stabil, dan backup konfigurasi rutin. 3. Monitoring Kinerja: Pemantauan traffic (deteksi bottleneck/overload), pengecekan error (CRC/Collision), serta monitoring suhu dan daya. 4. Tindakan Preventif: Reboot terjadwal, pengecekan kestabilan daya (UPS), dan pengaturan logging event. 5. Troubleshooting (Korektif): Penanganan port mati, penggantian modul SFP/kabel rusak, dan reset konfigurasi saat kritis. 6. Dokumentasi: Pencatatan riwayat perbaikan, diagram topologi port, dan alokasi perangkat.', 0, 'med', NULL, NULL, NULL, 2, 1, 1, 1, 1, 524227);
